static void mock_startup_trace_append(char operation) {
        if (!mock_startup_trace_enabled ||
            mock_startup_trace_length >=
                    (int)sizeof(mock_startup_trace) - 1) {
                return;
        }
        mock_startup_trace[mock_startup_trace_length++] = operation;
        mock_startup_trace[mock_startup_trace_length] = 0;
}

int Create(int priority, void (*function)()) {
        (void)priority;
        (void)function;
        return 1;
}
int MyTid(void) { return 1; }
int MyParentTid(void) { return 1; }
void Yield(void) {}
void Exit(void) {}
int Send(int tid, const char *msg, int msglen, char *reply, int rplen) {
        if (mock_send_capture_enabled && msg && reply &&
            msglen == (int)sizeof(tc2_dispatch_request) &&
            rplen == (int)sizeof(tc2_dispatch_reply)) {
                mock_send_tid = tid;
                mock_send_request =
                        *(const tc2_dispatch_request *)msg;
                tc2_dispatch_reply *dispatch_reply =
                        (tc2_dispatch_reply *)reply;
                dispatch_reply->status = mock_send_reply_status;
                dispatch_reply->affected = 1;
                return (int)sizeof(*dispatch_reply);
        }
        return -1;
}
int Receive(int *tid, char *msg, int msglen) {
        if (mock_scripted_receive_enabled &&
            !mock_scripted_receive_delivered) {
                if (!tid || !msg ||
                    msglen < (int)sizeof(mock_scripted_request)) {
                        return -1;
                }
                *tid = 42;
                *(tc2_dispatch_request *)msg = mock_scripted_request;
                mock_scripted_receive_delivered = 1;
                return (int)sizeof(mock_scripted_request);
        }
        if (mock_escape_on_receive) {
                longjmp(mock_dispatch_server_escape, 1);
        }
        return -1;
}
int Reply(int tid, const char *reply, int rplen) {
        if (mock_scripted_receive_enabled && tid == 42 && reply &&
            rplen == (int)sizeof(mock_scripted_reply)) {
                mock_scripted_reply =
                        *(const tc2_dispatch_reply *)reply;
                mock_scripted_reply_seen = 1;
        }
        return rplen;
}
int AwaitEvent(int event_type) {
        if (event_type != EVENT_TIMER) {
                ++mock_await_event_wrong_type;
        }
        mock_startup_trace_append('W');
        ++mock_await_event_calls;
        if (mock_await_event_status >= 0 &&
            mock_sensor_ready_after_waits > 0 &&
            mock_await_event_calls >=
                    mock_sensor_ready_after_waits) {
                mock_sensor_snapshot.courier_ready = 1;
        }
        return mock_await_event_status;
}
