int CanGetHealth(int tid, can_health_t *health) {
        (void)tid;
        if (!health) return -1;
        if (mock_can_heartbeats_advance) {
                ++mock_can_health.tx_notifier_heartbeat;
                ++mock_can_health.rx_notifier_heartbeat;
        }
        *health = mock_can_health;
        return 0;
}
int CanRegisterTurnoutAuthority(int tid) {
        return tid >= 1 ? 0 : -1;
}
int CanTrainSetSpeed(int tid, int train, int speed) {
        (void)tid;
        if (train < 1 || train > 255 || speed < 0 || speed > 120) {
                return -1;
        }
        if (speed == 0) {
                ++mock_zero_speed_calls;
                ++mock_stop_commands_by_train[train];
        } else {
                ++mock_direct_positive_speed_calls;
        }
        ++mock_can_health.tx_completed;
        return 0;
}
int CanTrainSetSpeedPriority(int tid, int train, int speed) {
        int status = CanTrainSetSpeed(tid, train, speed);
        if (status == 0 && speed == 0 &&
            mock_stop_confirmation_tick_advance > 0) {
                mock_now += mock_stop_confirmation_tick_advance;
        } else if (status == 0 && speed > 0 &&
                   mock_positive_confirmation_tick_advance > 0) {
                mock_now +=
                        mock_positive_confirmation_tick_advance;
        }
        return status;
}
int CanTrainSetSpeedBatch(int tid, const int *trains,
                          const int *speeds, int count) {
        (void)tid;
        if (!trains || !speeds || count < 1 ||
            count > TC2_DISPATCH_MAX_JOBS) {
                return -1;
        }
        for (int index = 0; index < count; ++index) {
                if (trains[index] < 1 || trains[index] > 255 ||
                    speeds[index] < 1 || speeds[index] > 120) {
                        return -1;
                }
        }
        if (mock_speed_batch_busy_count > 0) {
                --mock_speed_batch_busy_count;
                return CAN_SEND_BUSY;
        }
        ++mock_speed_batch_calls;
        mock_speed_batch_count = count;
        for (int index = 0; index < count; ++index) {
                mock_speed_batch_trains[index] = trains[index];
                mock_speed_batch_speeds[index] = speeds[index];
        }
        ++mock_control_order;
        mock_positive_speed_calls += count;
        if (mock_first_positive_order == 0) {
                mock_first_positive_order = mock_control_order;
        }
        mock_can_health.tx_completed += (unsigned int)count;
        mock_batch_status.token = 1;
        mock_batch_status.state = mock_batch_auto_complete ?
                CAN_BATCH_COMPLETE : CAN_BATCH_PENDING;
        mock_batch_status.total = count;
        mock_batch_status.confirmed =
                mock_batch_auto_complete ? count : 0;
        return 1;
}
int CanTrainEmergencyStopBatch(int tid, const int *trains,
                               int count) {
        (void)tid;
        if (!trains || count < 1 ||
            count > TC2_DISPATCH_MAX_JOBS) {
                return -1;
        }
        for (int index = 0; index < count; ++index) {
                if (trains[index] < 1 || trains[index] > 255) {
                        return -1;
                }
                ++mock_stop_commands_by_train[trains[index]];
        }
        mock_emergency_status.token = 2;
        mock_emergency_status.state = CAN_BATCH_COMPLETE;
        mock_emergency_status.total = count;
        mock_emergency_status.confirmed = count;
        mock_can_health.tx_completed += (unsigned int)count;
        return 2;
}
int CanGetBatchStatus(int tid, unsigned int token,
                      can_batch_status_t *status) {
        (void)tid;
        if (!status) return -1;
        if (token == mock_batch_status.token) {
                *status = mock_batch_status;
        } else if (token == mock_emergency_status.token) {
                *status = mock_emergency_status;
        } else if (token == mock_turnout_status.token) {
                *status = mock_turnout_status;
        } else {
                return -1;
        }
        return 0;
}
int CanCancelBatch(int tid, unsigned int token) {
        (void)tid;
        ++mock_cancel_batch_calls;
        if (mock_cancel_batch_force_fail) {
                return -1;
        }
        if (token == mock_batch_status.token &&
            mock_batch_status.state == CAN_BATCH_PENDING) {
                mock_batch_status.state = CAN_BATCH_FAILED;
                return 0;
        }
        if (token == mock_turnout_status.token &&
            mock_turnout_status.state == CAN_BATCH_PENDING) {
                mock_turnout_status.state = CAN_BATCH_FAILED;
                return 0;
        }
        return -1;
}
int CanTrainReverse(int tid, int train) {
        (void)tid;
        if (train < 1 || train > 255) return -1;
        ++mock_can_health.tx_completed;
        ++mock_reverse_calls;
        mock_last_reverse_order = ++mock_control_order;
        return 0;
}
int CanTrainReversePriority(int tid, int train) {
        int status = CanTrainReverse(tid, train);
        if (status == 0 &&
            mock_reverse_confirmation_tick_advance > 0) {
                mock_now += mock_reverse_confirmation_tick_advance;
        }
        return status;
}
int CanSwitch(int tid, int switch_number, char direction) {
        (void)tid;
        if (switch_number < 1 ||
            (direction != 'S' && direction != 'C') ||
            mock_switch_count >= TRACK_MAX * 2) {
                return -1;
        }
        if (mock_switch_required_owner_train > 0 &&
            (mock_switch_required_owner_node < 0 ||
             mock_switch_required_owner_node >= TRACK_MAX ||
             mock_reservations.owner_by_node[
                     mock_switch_required_owner_node] !=
                     mock_switch_required_owner_train)) {
                mock_switch_without_required_owner = 1;
        }
        mock_switch_number[mock_switch_count] = switch_number;
        mock_switch_direction[mock_switch_count] = direction;
        ++mock_switch_count;
        ++mock_can_health.tx_completed;
        return 0;
}
int CanSwitchBatch(int tid, const int *switch_numbers,
                   const char *directions, int count) {
        (void)tid;
        if (!switch_numbers || !directions || count < 1 ||
            count > CAN_COMMAND_BATCH_MAX) {
                return -1;
        }
        if (mock_turnout_busy_count > 0) {
                --mock_turnout_busy_count;
                return CAN_SEND_BUSY;
        }
        for (int index = 0; index < count; ++index) {
                if (CanSwitch(
                            tid, switch_numbers[index],
                            directions[index]) < 0) {
                        return -1;
                }
        }
        mock_turnout_status.token = 3;
        mock_turnout_status.state = mock_turnout_auto_complete ?
                CAN_BATCH_COMPLETE : CAN_BATCH_PENDING;
        mock_turnout_status.total = count;
        mock_turnout_status.confirmed =
                mock_turnout_auto_complete ? count : 0;
        return 3;
}

void TrainSensorInitSnapshot(train_sensor_snapshot_t *snapshot) {
        unsigned char *bytes = (unsigned char *)snapshot;
        for (unsigned int index = 0;
             index < sizeof(*snapshot); ++index) {
                bytes[index] = 0;
        }
        for (int sensor = 0; sensor < TRAIN_SENSOR_COUNT; ++sensor) {
                snapshot->last_attributed_train_by_sensor[sensor] = 0;
        }
        for (int train = 0; train < 256; ++train) {
                snapshot->position_by_train[train] = -1;
        }
}
void TrainSensorJournalInit(train_sensor_journal_t *journal) {
        unsigned char *bytes = (unsigned char *)journal;
        for (unsigned int index = 0;
             index < sizeof(*journal); ++index) {
                bytes[index] = 0;
        }
}
int TrainSensorJournalQuery(
        const train_sensor_journal_t *journal, int train,
        unsigned int after_sequence, train_sensor_event_batch_t *batch) {
        if (!journal || !batch || train < 1 || train > 255) return -1;
        batch->count = 0;
        batch->has_more = 0;
        batch->lost =
                journal->dropped_sequence_by_train[train] != 0 &&
                after_sequence <
                        journal->dropped_sequence_by_train[train];
        batch->newest_sequence =
                journal->newest_sequence_by_train[train];
        for (int offset = 0; offset < journal->count; ++offset) {
                int index = (journal->head + offset) %
                        TRAIN_SENSOR_JOURNAL_CAPACITY;
                const train_sensor_attributed_event_t *event =
                        &journal->entries[index];
                if (event->train != train ||
                    event->sequence <= after_sequence) {
                        continue;
                }
                if (batch->count >=
                    TRAIN_SENSOR_EVENT_BATCH_CAPACITY) {
                        batch->has_more = 1;
                        break;
                }
                batch->events[batch->count++] = *event;
        }
        return 0;
}

static void mock_record_sensor_event(
        const train_sensor_attributed_event_t *event) {
        int index = (mock_sensor_journal.head +
                     mock_sensor_journal.count) %
                TRAIN_SENSOR_JOURNAL_CAPACITY;
        mock_sensor_journal.entries[index] = *event;
        ++mock_sensor_journal.count;
        mock_sensor_journal.newest_sequence_by_train[event->train] =
                event->sequence;
}

