static int check_provisional_endpoint_all_speeds(void) {
        /*
         * The physical D7 endpoint stays fixed at +280 mm.  Only the
         * supervised point controller receives a velocity-dependent
         * correction fitted from all six measured command speeds.
         * Exercise every accepted command speed so interpolation cannot
         * accidentally become a special case for either measured speed.
         */
        for (int speed = 1; speed <= 120; ++speed) {
                tc2_dispatch_request request;
                reset_dispatch_test();
                clear_request(
                        &request,
                        TC2_DISPATCH_MSG_STAGE_CALIBRATION);
                request.train = 14;
                request.start_index = 0;
                request.speed = speed;
                request.destination_index = 6;
                if (stage_job(&request) < 0) return -1;

                int slot = find_train_job(14);
                if (slot < 0) return -1;
                tc2_dispatch_job_snapshot *job =
                        &dispatch_jobs[slot];
                tc2_dispatch_runtime *runtime =
                        &dispatch_runtime[slot];
                job->state = TC2_JOB_WAITING;
                job->queue_sequence =
                        ++dispatch_queue_sequence;
                runtime->queue_sequence =
                        job->queue_sequence;
                runtime->wait_since_tick = mock_now;
                runtime->launch_epoch = 1;
                job->job_launch_epoch = 1;
                if (prepare_waiting_job(slot, mock_now) != 0) {
                        fprintf(stderr,
                                "speed %d endpoint preparation failed "
                                "state=%d failure=%d target=%d side=%d\n",
                                speed, job->state,
                                job->failure_reason,
                                job->target_node,
                                job->selected_destination_side);
                        return -1;
                }
                if (drive_preparing_pipeline_to_ready(slot) < 0) {
                        fprintf(stderr,
                                "speed %d endpoint preparation did not "
                                "settle its hard-next zone\n",
                                speed);
                        return -1;
                }

                int correction =
                        Tc2MotionD7EndpointCorrectionMm(speed);
                const tc2_track_destination_side *selected_side =
                        Tc2TrackDestinationSide(
                                6, job->selected_destination_side);
                int expected_target = selected_side ?
                        TrackFindNodeByName(
                                dispatch_track,
                                selected_side->anchor_sensor) : -1;
                if (correction != 0 ||
                    !selected_side ||
                    job->state != TC2_JOB_READY ||
                    job->target_node != expected_target ||
                    job->destination_base_offset_mm != 305 ||
                    job->destination_speed_correction_mm != correction ||
                    job->destination_offset_mm != 305 ||
                    job->destination_distance_mm <= 305 ||
                    job->route_distance_mm !=
                            job->destination_distance_mm ||
                    job->destination_route_offset <=
                            job->target_route_offset) {
                        fprintf(stderr,
                                "speed %d endpoint fit/route failed: "
                                "base=%d correction=%d/%d offset=%d "
                                "distance=%d state=%d\n",
                                speed,
                                job->destination_base_offset_mm,
                                job->destination_speed_correction_mm,
                                correction,
                                job->destination_offset_mm,
                                job->destination_distance_mm,
                                job->state);
                        return -1;
                }
        }
        return 0;
}

